import json
s=json.load(open('SCENE.json'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items():
            kp=p+'/'+k
            if isinstance(v,(dict,list)): walk(v,kp)
            else:
                if any(t in k.lower() for t in ('catalog','manifest','loader','resolve','path','index','root')):
                    print(kp,'=',repr(v)[:160])
    elif isinstance(o,list):
        if o and not isinstance(o[0],(dict,list)): return
        for i,v in enumerate(o[:3]): walk(v,p+f'[{i}]')
walk(s)
